#!/usr/bin/env python3
"""Verify the offline fictional sample with cosign, then evaluate its evidence with OPA.
Run in the directory containing the six downloaded sample files.
Tested with cosign 3.0.6 and OPA 1.19.1; no network or online identity is required.
The key and policy pins below are trusted configuration, not values supplied by a workload.
"""
import hashlib
import json
from pathlib import Path
import subprocess
import sys
import tempfile

PUBLIC_KEY_SHA256 = "1f677545f078de476414aad2cdad75ce69bf85f4ecb498903867dfc9c9d475f5"
POLICY_SHA256 = "fc9cc2159bd6a6ff79e4cde3521912d4ece78de623b88c44b89c9d50b30260a3"

def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate statement field")
        result[key] = value
    return result

def verify():
    names = ["artifact.txt", "statement.json", "sample.pub", "sample.bundle.json", "sample-policy.rego"]
    payloads = {name: Path(name).read_bytes() for name in names}
    if any(len(data) > 1024 * 1024 for data in payloads.values()):
        raise ValueError("Sample file exceeds the 1 MiB limit")
    if hashlib.sha256(payloads["sample.pub"]).hexdigest() != PUBLIC_KEY_SHA256:
        raise ValueError("Public key does not match the trusted pin")
    if hashlib.sha256(payloads["sample-policy.rego"]).hexdigest() != POLICY_SHA256:
        raise ValueError("Policy does not match the trusted pin")
    # Snapshot once: both engines see the same bytes even if the original files change.
    with tempfile.TemporaryDirectory(prefix="provenance-check-") as directory:
        work = Path(directory)
        for name, data in payloads.items():
            (work / name).write_bytes(data)
        signature = subprocess.run([
            "cosign", "verify-blob", "--key", "sample.pub", "--bundle", "sample.bundle.json",
            "--insecure-ignore-tlog", "statement.json",
        ], cwd=work, capture_output=True, text=True, timeout=30)
        # This offline pinned-key example omits transparency-log verification explicitly.
        # It still requires the signature and signed statement bytes to verify.
        if signature.returncode != 0:
            raise ValueError("Signature or signed-statement verification failed")
        statement = json.loads(payloads["statement.json"], object_pairs_hook=unique_object)
        evidence = {"statement": statement, "expected": {
            "artifact_sha256": hashlib.sha256(payloads["artifact.txt"]).hexdigest(),
        }}
        (work / "verified-input.json").write_text(json.dumps(evidence))
        policy = subprocess.run([
            "opa", "eval", "--strict", "--fail", "--format=json", "--data", "sample-policy.rego",
            "--input", "verified-input.json", "data.sample.provenance.allow == true",
        ], cwd=work, capture_output=True, text=True, timeout=30)
        if policy.returncode != 0:
            raise ValueError("Verified statement does not authorize this artifact and builder")
        answer = json.loads(policy.stdout)
        if answer["result"][0]["expressions"][0]["value"] is not True:
            raise ValueError("Verified statement does not authorize this artifact and builder")
    print("Accepted: trusted signature, artifact digest and declared sample builder match")

if __name__ == "__main__":
    try:
        verify()
    except (OSError, ValueError, KeyError, IndexError, subprocess.SubprocessError) as error:
        print("Rejected: " + str(error), file=sys.stderr)
        sys.exit(1)
